1	export type Cell = [x: number, y: number];
2	
3	// A cell's identity is its position, but arrays compare by reference, so the
4	// same position reached twice is two distinct values. This key restores
5	// identity: equal positions produce equal keys.
6	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
7	
8	// Membership test for the current generation, closed over its own index.
9	type LiveSet = (cell: Cell) => boolean;
10	
11	const OFFSETS = [-1, 0, 1];
12	
13	const isSelf = ([dx, dy]: Cell): boolean => dx === 0 && dy === 0;
14	
15	const NEIGHBOR_OFFSETS: Cell[] = OFFSETS.flatMap((dx) =>
16	  OFFSETS.map((dy): Cell => [dx, dy]),
17	).filter((offset) => !isSelf(offset));
18	
19	const neighborsOf = ([x, y]: Cell): Cell[] =>
20	  NEIGHBOR_OFFSETS.map(([dx, dy]): Cell => [x + dx, y + dy]);
21	
22	const countLiveNeighbors = (cell: Cell, isLive: LiveSet): number =>
23	  neighborsOf(cell).filter(isLive).length;
24	
25	// Fewer than 2 neighbors is underpopulation, more than 3 is overpopulation;
26	// both are death. Only this band survives.
27	const MIN_NEIGHBORS_TO_SURVIVE = 2;
28	const MAX_NEIGHBORS_TO_SURVIVE = 3;
29	
30	const survives = (liveNeighborCount: number): boolean =>
31	  liveNeighborCount >= MIN_NEIGHBORS_TO_SURVIVE &&
32	  liveNeighborCount <= MAX_NEIGHBORS_TO_SURVIVE;
33	
34	const NEIGHBORS_TO_BE_BORN = 3;
35	
36	const isBorn = (liveNeighborCount: number): boolean =>
37	  liveNeighborCount === NEIGHBORS_TO_BE_BORN;
38	
39	const liveSet = (liveCells: Cell[]): LiveSet => {
40	  const keys = new Set(liveCells.map(keyOf));
41	  return (cell) => keys.has(keyOf(cell));
42	};
43	
44	const deduplicate = (cells: Cell[]): Cell[] => [
45	  ...new Map(cells.map((cell) => [keyOf(cell), cell])).values(),
46	];
47	
48	// Only cells touching a live cell can change state, so the rest of the
49	// infinite grid never needs to be examined.
50	const cellsToEvaluate = (liveCells: Cell[]): Cell[] =>
51	  deduplicate(liveCells.flatMap((cell) => [cell, ...neighborsOf(cell)]));
52	
53	export function nextGeneration(liveCells: Cell[]): Cell[] {
54	  const isLive = liveSet(liveCells);
55	  return cellsToEvaluate(liveCells).filter((cell) => {
56	    const liveNeighborCount = countLiveNeighbors(cell, isLive);
57	    return isLive(cell)
58	      ? survives(liveNeighborCount)
59	      : isBorn(liveNeighborCount);
60	  });
61	}
